59	    method: 'PUT',
60	    body: JSON.stringify({ summary: '', ...fields, version }),
61	  });
62	  const data = await res.json().catch(() => ({}));
63	  return { status: res.status, article: data.article, error: data.error };
64	}
65	
66	// Puts the page into the post-409 state: it opened v1, holds `mine` in the
67	// form, and another tab has since saved v2, so the page's save is rejected
68	// with the side-by-side conflict comparison.
69	async function stageStaleConflict(server, page, v1, mine, v2) {
70	  const article = await seedAndReload(server, page, v1);
71	  await ui.clickEdit(page, v1.title);
72	  await ui.waitLoadedDraft(page);
