1	// Minimal Chrome DevTools Protocol client built only on Node 24 primitives
2	// (global WebSocket/fetch, child_process). The product itself ships with no
3	// dependencies, and the regression suite keeps that property: it drives the
4	// real page in the real system Chrome instead of a mocked DOM.
5	import { spawn } from 'node:child_process';
6	import { existsSync, mkdtempSync, rmSync } from 'node:fs';
7	import { tmpdir } from 'node:os';
8	import { join } from 'node:path';
9	import { setTimeout as sleep } from 'node:timers/promises';
