11	let nextId = 1;
12	
13	class CdpSession {
14	  constructor(connection, sessionId) {
15	    this.conn = connection;
16	    this.sessionId = sessionId;
17	  }
18	
19	  send(method, params = {}) {
20	    return this.conn.send(method, params, this.sessionId);
21	  }
22	}
23	
24	class CdpConnection {
25	  constructor(ws) {
26	    this.ws = ws;
27	    this.pending = new Map();
28	    this.eventListeners = [];
29	    ws.addEventListener('message', (event) => {
30	      const msg = JSON.parse(event.data);
31	      if (msg.id && this.pending.has(msg.id)) {
32	        const { resolve, reject } = this.pending.get(msg.id);
33	        this.pending.delete(msg.id);
