  var readGate = { enabled: false, hits: 0, pending: [] };
  // null = off; 404/500 = respond with that status once; 'network' = reject once.
  var failNextRead = null;

  // Armed via localStorage before a reload so they are active before the
  // page script's first load() runs. Consumed once on installation.
  var holdMode = localStorage.getItem('__qtest_list_hold');
  localStorage.removeItem('__qtest_list_hold');
  var failNextList = localStorage.getItem('__qtest_list_fail');
  localStorage.removeItem('__qtest_list_fail');
  var listGate = {
    enabled: holdMode !== null || failNextList !== null,
    hits: 0,
    pending: [],
    captured: 0,
    mode: holdMode === 'captured' ? 'captured' : 'deferred'
  };

  function methodOf(init) { return ((init && init.method) || 'GET').toUpperCase(); }
  function pathOf(input) {
    var url = typeof input === 'string' ? input : ((input && input.url) || '');
    return url.split('?')[0];
  }
  function isSaveCall(path, method) {
    if (method !== 'POST' && method !== 'PUT') return false;
    return path === '/api/articles' || /^\\/api\\/articles\\/[^/]+$/.test(path);
  }
  function isItemRead(path, method) {
    return method === 'GET' && /^\\/api\\/articles\\/[^/]+$/.test(path);
