          failNextList = null;
          listFailureResult(mode).then(resolve, reject);
        });
      });
    }
    if (listGate.mode === 'captured') {
      var captured = origFetch(input, init);
      captured.then(function () { listGate.captured++; }, function () { listGate.captured++; });
      return new Promise(function (resolve) {
        listGate.pending.push(function () { resolve(captured); });
      });
    }
    return new Promise(function (resolve) {
      listGate.pending.push(function () { resolve(origFetch(input, init)); });
    });
